#include <bits/stdc++.h>
using namespace std;
const int MAX=510;
typedef pair<int,int> Pair;
#define make_pair mp
#define first fi
#define second se

int total_n, total_m, modulus, C[MAX][MAX];
Pair dp_table[MAX][MAX];

int add_mod(int a, int b) {
    return a + b >= modulus ? a + b - modulus : a + b;
}

Pair operator+(const Pair &a, const Pair &b) {
    return make_pair(add_mod(a.fi, b.fi), add_mod(a.se, b.se));
}

Pair operator*(const Pair &a, const Pair &b) {
    long long fi_part = 1LL * a.fi * b.fi % modulus;
    long long se_part = (1LL * a.fi * b.se + 1LL * a.se * b.fi) % modulus;
    return make_pair((int)fi_part, (int)se_part);
}

int sum_range(int left, int right) {
    return (left + right) * (right - left + 1) / 2;
}

int main() {
#ifdef LOCAL
    freopen("a.in", "r", stdin);
    freopen("a.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total_n >> total_m >> modulus;
    for (int i = 0; i < MAX; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = add_mod(C[i - 1][j], C[i - 1][j - 1]);
        }
    }
    for (int i = 0; i <= total_n; i++) {
        dp_table[i][0] = make_pair(1, 0);
        for (int j = 1; j <= i && j <= total_m; j++) {
            if (i != j) {
                for (int k = 1; k <= i; k++) {
                    dp_table[i][j] = dp_table[i][j] + dp_table[k - 1][k - 1] * dp_table[i - k][j - k + 1] * make_pair(C[j][k - 1], 0);
                }
            } else {
                for (int k = 1; k <= i; k++) {
                    auto term1 = dp_table[k - 1][k - 1];
                    auto term2 = dp_table[i - k][i - k];
                    auto comb = make_pair(C[i - 1][k - 1], 0);
                    int factor = i + 1 - sum_range(1, k) + sum_range(k + 1, i) - k * (i - k);
                    auto factor_pair = make_pair(factor, 0);
                    dp_table[i][j] = dp_table[i][j] + term1 * term2 * comb * factor_pair;
                }
            }
        }
    }
    cout << dp_table[total_n][total_m].second;
    return 0;
}
